import{_ as a,a0 as l,w as d,s as r,I as p,x as e,a1 as n,A as i,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"已經會用Git了？不會這十招怎麼行 | LCTT x X-CMD","titleTemplate":false,"description":"已經會用Git了？不會這十招怎麼行 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"已經會用Git了？不會這十招怎麼行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"已經會用Git了？不會這十招怎麼行 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140620 Tips to Push Your Git Skills to the Next Level","title":"已經會用Git了？不會這十招怎麼行","tag":"201407","desc":""},"relativePath":"201407/20140620 Tips to Push Your Git Skills to the Next Level.md","filePath":"[post].md"}'),c={name:"201407/20140620 Tips to Push Your Git Skills to the Next Level.md"};function g(h,t,m,u,f,b){const o=l("Link");return d(),r("div",null,[t[16]||(t[16]=p("h1",{id:"已經會用git了-不會這十招怎麼行",tabindex:"-1"},[e("已經會用Git了？不會這十招怎麼行 "),p("a",{class:"header-anchor",href:"#已經會用git了-不會這十招怎麼行","aria-label":"Permalink to “已經會用Git了？不會這十招怎麼行”"},"​")],-1)),p("p",null,[t[2]||(t[2]=e("之前我們發了一些教程讓你熟悉",-1)),n(o,{href:"http://www.sitepoint.com/git-for-beginners/"},{default:i(()=>[...t[0]||(t[0]=[e("Git基礎",-1)])]),_:1}),t[3]||(t[3]=e("和",-1)),n(o,{href:"http://www.sitepoint.com/getting-started-git-team-environment/"},{default:i(()=>[...t[1]||(t[1]=[e("在團隊合作環境中使用Git",-1)])]),_:1}),t[4]||(t[4]=e(".我們討論的這些Git命令足夠讓一個開發者在Git的世界裏生存下去。在這篇教程裏，我們試着探索如何高效地管理你的時間以及如何充分利用Git提供的特性。",-1))]),t[17]||(t[17]=s(`<blockquote><p>注意：這裏介紹的命令中有的包含方括號(例如：<code>git add -p [file_name]</code>)。在這些例子中，你應該用你自己的數字、標識符等替代方括號裏的內容，並且去掉方括號。</p></blockquote><h3 id="_1-git自動補全" tabindex="-1">1. Git自動補全 <a class="header-anchor" href="#_1-git自動補全" aria-label="Permalink to “1. Git自動補全”">​</a></h3><p>如果你在命令列環境中運行Git命令，每次都手動地逐個輸入命令是一件很無聊的事。為此，你可以花幾分鐘時間配置一下Git命令的自動補全功能。</p><p>在*nix系統運行下列命令下載自動補全腳本：</p><pre><code>cd ~
curl https://raw.github.com/git/git/master/contrib/completion/git-completion.bash -o ~/.git-completion.bash
</code></pre><p>然後，添加下面的行到你的~/.bash_profile文件：</p><pre><code>if [ -f ~/.git-completion.bash ]; then
    . ~/.git-completion.bash
fi
</code></pre><p>儘管我之前已經提到過，但我還是想再強調一下：如果你想使用完整的Git特性，你絕bi應該切換到命令列環境。</p><h3 id="_2-在git中忽略文件" tabindex="-1">2. 在Git中忽略文件 <a class="header-anchor" href="#_2-在git中忽略文件" aria-label="Permalink to “2. 在Git中忽略文件”">​</a></h3><p>你是不是對出現在你Git庫裏面的編譯生成文件（比如<code>.pyc</code>)感到很無語？或者你是不是很厭惡不小心將他們添加到了Git？直接看這裏，這裏有一個方法可以讓你告訴Git忽略所有這些文件和目錄。只需要創建一個名字為<code>.gitignore</code>的文件，裏面列出你不想要Git跟蹤的文件和目錄。可以用感嘆號(!)列出例外情況。</p><pre><code>*.pyc
*.exe
my_db_config/
 
!main.pyc
</code></pre><h3 id="_3-誰動了我的代碼" tabindex="-1">3. 誰動了我的代碼？ <a class="header-anchor" href="#_3-誰動了我的代碼" aria-label="Permalink to “3. 誰動了我的代碼？”">​</a></h3><p>當事情出了亂子時立馬責怪別人這是人類的天性。如果你的服務器程序不能正常工作了，要找出罪魁禍首是非常簡單的--只需要執行<code>git blame</code>。這個命令告訴你文件裏的每一行的作者是誰，最後改動那一行的提交，以及提交的時間戳。</p><pre><code>git blame [file_name]
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946443git-ninja-01.png" alt="git blame demonstration"></p><p>在下面的截圖裏，你可以看到在一個更大的庫裏這個命令的輸出是什麼樣的：</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946441git-ninja-02.png" alt="git blame on the ATutor repository"></p><h3 id="_4-查看庫的歷史" tabindex="-1">4. 查看庫的歷史 <a class="header-anchor" href="#_4-查看庫的歷史" aria-label="Permalink to “4. 查看庫的歷史”">​</a></h3><p>在之前的教程裏，我們已經看過了如何使用<code>git log</code>命令。不管怎樣，有3個選項你應該知道。</p><ul><li><strong>--oneline</strong> - 壓縮每次的提交信息，只保留一個縮減的Hash值和説明文字，然後把這些都展示在一行裏。</li><li><strong>--graph</strong> - 這個選項將在左邊畫出一個文字界面的提交歷史圖。如果你只有一個分支，用這個選項查看歷史時是沒什麼意義的。</li><li><strong>--all</strong> - 顯示所有分支歷史。</li></ul><p>這是這3個選項合起來使用的效果：</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946444git-ninja-03.png" alt="Use of git log with all, graph and oneline"></p><h3 id="_5-不要丟失對某個提交的跟蹤" tabindex="-1">5. 不要丟失對某個提交的跟蹤 <a class="header-anchor" href="#_5-不要丟失對某個提交的跟蹤" aria-label="Permalink to “5. 不要丟失對某個提交的跟蹤”">​</a></h3><p>假設你提交了一些不需要的東西，然後你進行了hard重置回到之前的狀態。後來，你發現在這個過程中你丟失了其他一些重要的信息，你想要把這些信息找回來，或者至少可以查看一下這些信息。這就需要<code>git reflog</code>幫忙。</p><p>簡單的<code>git log</code>只能告訴你最近的提交，這個提交的父提交，父提交的父提交，等等。但是<code>git reflog</code>是一個HEAD指向的提交的列表。記住，這個列表依賴於你自己的本地操作環境，它不是庫的一部分，也不包含在push或者merge中。</p><p>如果執行<code>git log</code>命令，可以看到提交歷史，這是我的庫的一部分：</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946446git-ninja-04.png" alt="Project history"></p><p>但是，<code>git reflog</code>命令顯示了一個被我用hard重置丟掉的提交(<code>b1b0ee9</code>-<code>HEAD@{4}</code>).</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946447git-ninja-05.png" alt="Git reflog"></p><h3 id="_6-暫存文件的一部分更改以便進行一次提交" tabindex="-1">6. 暫存文件的一部分更改以便進行一次提交 <a class="header-anchor" href="#_6-暫存文件的一部分更改以便進行一次提交" aria-label="Permalink to “6. 暫存文件的一部分更改以便進行一次提交”">​</a></h3><p>通常依據特性來提交是一個好的實踐方法，意思是説，每一個提交都只添加一個特性或者修復一個bug。想一下如果你一次修復了兩個bug或者添加了兩個特性但是都還沒有逐個提交該怎麼辦。這種場景下，你可以將他們一起提交。但是有一個更好的辦法：單獨暫存這些文件，然後分開提交。</p><p>讓我們假設你對一個文件做了多個更改，然後想讓這些更改分開提交。這時，我們用帶<code>-p</code>的添加命令。</p><pre><code>git add -p [file_name]
</code></pre><p>我們來試試這種用法。我添加了3個新行到<code>file_name</code>，但是我只想讓第1行和第3行出現在我的提交裏。讓我們看看<code>git diff</code>的輸出是什麼樣的。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946449git-ninja-06.png" alt="Changes in repo"></p><p>然後，我們看看帶<code>-p</code>選項的<code>add</code>命令會發生什麼。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946450git-ninja-07.png" alt="Running add with -p"></p><p>看起來Git認為所有的更改都是同一個目的的一部分，所以把他們分組到同一個塊裏。這時，你可以：</p><ul><li>輸入 y 暫存塊</li><li>輸入 n 不暫存塊</li><li>輸入 e 手動編輯塊</li><li>輸入 d 退出或者跳轉到下一個文件</li><li>輸入 s 分割塊</li></ul><p>在我們這個例子中，我們想把這個塊分割成更小的部分，然後選擇其中一些忽略另外一些。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946452git-ninja-08.png" alt="Adding all hunks"></p><p>如你所見，我們已經逐個添加了第1和第3行，忽略了第2行。你可以看到庫的狀態並且進行一次提交。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946454git-ninja-09.png" alt="Repository after selectively adding a file"></p><h3 id="_7-合併多個提交" tabindex="-1">7. 合併多個提交 <a class="header-anchor" href="#_7-合併多個提交" aria-label="Permalink to “7. 合併多個提交”">​</a></h3><p>為了進行核查或者發起一個合併請求（這經常發生在開源項目裏），對代碼進行了修改提交。但在最後代碼被接受之前，你也許會需要修改你的代碼。於是你修改代碼，但是下一次核查的時候又一次需要進行修改。不知不覺中，你就已經有了好幾個提交。理論上你應該用rebase命令把他們合併起來。</p><pre><code>git rebase -i HEAD~[number_of_commits]
</code></pre><p>如果你想合併最後的兩次提交，你應該運行下面的命令。</p><pre><code>git rebase -i HEAD~2
</code></pre><p>一旦你運行這個命令，你將進入一個交互式界面，它將詢問你想要合併哪些提交。你<code>pick</code>(揀選)最近的提交然後<code>squash</code>(合併)舊的提交。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946455git-ninja-10.png" alt="Git squash interactive"></p><p>接着你應該提供一個對新提交的説明。這個過程會重寫你的提交歷史。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946457git-ninja-11.png" alt="Adding a commit message"></p><h3 id="_8-儲藏沒有提交的更改" tabindex="-1">8. 儲藏沒有提交的更改 <a class="header-anchor" href="#_8-儲藏沒有提交的更改" aria-label="Permalink to “8. 儲藏沒有提交的更改”">​</a></h3><p>假設你正在修復一個bug或者添加一個特性，突然你被要求展示一下你的工作成果。你現在的工作還沒有完成，不夠進行一次提交。這時，<code>git stash</code>命令可以用來急救一下。Stash命令跟蹤你所有的更改，然後把他們儲藏起來以便以後使用。命令如下-</p><pre><code>git stash
</code></pre><p>可以多次儲藏更改，查看儲藏列表，你可以運行下面的命令：</p><pre><code>git stash list
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946458git-ninja-12.png" alt="Stash list"></p><p>如果你想取消儲藏，覆蓋當前的更改，你可以通過下面的命令使用儲藏：</p><pre><code>git stash apply
</code></pre><p>在最後的這個截圖裏，你可以看到每個儲藏都有一個標識符，是一個唯一的數字（儘管在這裏我們只有一個儲藏）。如果你想使用某個儲藏，你在apply命令後面加上這個唯一的標識符：</p><pre><code>git stash apply stash@{2}
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946461git-ninja-13.png" alt="After un-stashing changes"></p><h3 id="_9-檢查丟失的提交" tabindex="-1">9. 檢查丟失的提交 <a class="header-anchor" href="#_9-檢查丟失的提交" aria-label="Permalink to “9. 檢查丟失的提交”">​</a></h3><p>儘管<code>reflog</code>是一種檢查丟失提交的方法，大型的庫裏卻不太實用。這個時候，應該用<code>fsck</code>（文件系統檢查）命令。</p><pre><code>git fsck --lost-found
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946463git-ninja-14.png" alt="Git fsck results"></p><p>這裏你可以看到一個丟失的提交。你可以通過<code>git show [commit_hash]</code> 查看提交的更改或者通過運行<code>git merge [commit_hash]</code>命令進行恢復。</p><p><code>git fsck</code>跟<code>reflog</code>命令相比有一個優點。假設你刪除了一個遠程分支，然後clone了這個庫。用<code>fsck</code>命令你可以找到並且恢復這個刪除的遠程分支。</p><h3 id="_10-最佳選擇" tabindex="-1">10. 最佳選擇 <a class="header-anchor" href="#_10-最佳選擇" aria-label="Permalink to “10. 最佳選擇”">​</a></h3><p>之前我已經存記下了那些最優雅的Git命令。但是目前為止，<code>cherry-pick</code>命令是我最喜歡的Git命令，因為它直白的名字和實用的功能！</p><p>最簡單的情況下，<code>cherry-pick</code>從另一個分支裏選出單獨的一個提交，然後合併到當前分支。如果你正並行工作在兩個或者更多的分支上，你也許會發現一個存在於所有分支上的bug。如果你解決了一個分支上的這個bug，你可以揀選這個對應的提交應用到其他分支上，而不會弄亂其他文件或者提交。</p><p>讓我們來考慮一個可以使用這個命令的場景。我有兩個分支，我想揀選<code>b20fd14: Cleaned junk</code>這個提交到另一個分支上。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946465git-ninja-15.png" alt="Before cherry pick"></p><p>我切換到想要應用這個揀選出來的提交的分支，然後運行下面的命令：</p><pre><code>git cherry-pick [commit_hash]
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946467git-ninja-16.png" alt="After cherry pick"></p><p>儘管這次我們很乾淨的用了<code>cherry-pick</code>命令，但你應該知道這個命令經常會引起衝突，所以請小心使用。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>到了這裏，我們結束了這個能使你Git能力提升一個級別的列表。Git是最好的版本控制器，它能完成你能想像到的任何事情。所以，經常試着用Git挑戰你自己。一不小心你就會學到很多新東西。</p><hr>`,81)),p("p",null,[t[6]||(t[6]=e("via: ",-1)),n(o,{href:"http://www.sitepoint.com/10-tips-git-next-level/"},{default:i(()=>[...t[5]||(t[5]=[e("http://www.sitepoint.com/10-tips-git-next-level/",-1)])]),_:1})]),p("p",null,[t[9]||(t[9]=e("譯者：",-1)),n(o,{href:"https://github.com/CNprober"},{default:i(()=>[...t[7]||(t[7]=[e("love_daisy_love",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const w=a(c,[["render",g]]);export{k as __pageData,w as default};
